import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { change_of_owner_ship } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    ownerupdate: Boolean,
    rowInfo: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      forwardList: [],
      forwardUser: "",
      search: "",
      loading: false
    };
  },
  watch: {
    ownerupdate: {
      async handler() {
        if (this.ownerupdate == true) {
          this.$store.commit("Setnamesearch", "");
          await this.get_all_org_users();
          this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_details() {
      var data = this.$store.getters.GetUserObj;
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          if (element.user_email_id != data.user.user_email_id) {
            this.forwardList.push({
              full_user_name: element.full_user_name,
              user_email_id: element.user_email_id
            });
          }
        }
      });
    },
    async validate_aprrovals() {
      const {
        valid
      } = await this.$refs.form1.validate();
      if (valid) {
        this.ownershipChange();
      }
    },
    async ownershipChange() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(change_of_owner_ship, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: this.forwardUser
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.change_of_owner_ship);
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.$emit("successMsg", response.Message);
          this.$refs.form1.reset();
        } else {
          this.loading = false;

          // this.formCheck = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form1.reset();
    }
  }
};
